package com.ekayn.api.api; import com.ekayn.api.service.EmailNotVerifiedException; import org.springframework.http.*; import org.springframework.mail.MailException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(EmailNotVerifiedException.class) ResponseEntity<Map<String,String>> emailNotVerified(EmailNotVerifiedException e){return ResponseEntity.status(HttpStatus.FORBIDDEN).body(Map.of("code","EMAIL_NOT_VERIFIED","error",e.getMessage()));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));} @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,String>> notFound(NoSuchElementException e){return ResponseEntity.status(HttpStatus.NOT_FOUND).body(Map.of("error",e.getMessage()));} @ExceptionHandler(MailException.class) ResponseEntity<Map<String,String>> mail(MailException e){return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(Map.of("error","Le service d’envoi des emails est indisponible. Configurez le serveur SMTP ou démarrez Mailpit."));} }
